```js
function resolveBall(brick, entry, ball, prev) {
  // entry point
  const ex = prev.x + (ball.x - prev.x) * entry;
  const ey = prev.y + (ball.y - prev.y) * entry;
  const r = ball.r;
  const dLeft = ex - (brick.x - r);
  const dRight = brick.x + brick.w + r - ex;
  const dTop = ey - (brick.y - r);
  const dBottom = brick.y + brick.h + r - ey;
  const minX = Math.min(dLeft, dRight);
  const minY = Math.min(dTop, dBottom);
  const EPS = 1e-6;
  if (Math.abs(minX - minY) < EPS) {
    // corner
    if (dLeft <= dRight) ball.x = brick.x - r; else ball.x = brick.x + brick.w + r;
    if (dTop <= dBottom) ball.y = brick.y - r; else ball.y = brick.y + brick.h + r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (minX < minY) {
    // side hit
    if (dLeft < dRight) ball.x = brick.x - r; else ball.x = brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else {
    // top/bottom hit
    if (dTop < dBottom) ball.y = brick.y - r; else ball.y = brick.y + brick.h + r;
    ball.vy = -ball.vy;
  }
}
```

