```js
// Resolves the ball against the bricks: destroys every brick the ball's path
// (from `prev` to its current position) crosses, deflects the ball ONCE off
// the first brick it touches, and pushes it back outside. Returns the array
// of destroyed bricks (for scoring). `prev` is the ball position at the start
// of the frame; sweeping the segment `prev -> ball` is what stops the ball
// from tunnelling through a brick between frames (issue #1).
export function brickHit(ball, bricks, prev = null) {
  const p0x = prev ? prev.x : ball.x;
  const p0y = prev ? prev.y : ball.y;
  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const entry = segmentEntry(p0x, p0y, ball.x, ball.y, brick.x - ball.r, brick.x + brick.w + ball.r, brick.y - ball.r, brick.y + brick.h + ball.r);
    if (entry !== null) hits.push({ brick, entry });
  }
  if (hits.length === 0) return [];
  for (const h of hits) h.brick.alive = false;
  // Bounce off the brick the ball touches first (smallest entry time), so a
  // seam that overlaps two bricks at once deflects the ball exactly once.
  let first = hits[0];
  for (const h of hits) if (h.entry < first.entry) first = h;
  resolveBall(first.brick, first.entry, ball, p0x, p0y);
  return hits.map((h) => h.brick);
}
```

And resolveBall:

```js
function resolveBall(brick, entry, ball, p0x, p0y) {
  const ex = p0x + (ball.x - p0x) * entry;
  const ey = p0y + (ball.y - p0y) * entry;
  const r = ball.r;
  const dLeft = ex - (brick.x - r);
  const dRight = brick.x + brick.w + r - ex;
  const dTop = ey - (brick.y - r);
  const dBottom = brick.y + brick.h + r - ey;
  const minX = Math.min(dLeft, dRight);
  const minY = Math.min(dTop, dBottom);
  const EPS = 1e-6;
  if (Math.abs(minX - minY) < EPS) {
    // corner hit: bounce off both axes
    ball.x = dLeft <= dRight ? brick.x - r : brick.x + brick.w + r;
    ball.y = dTop <= dBottom ? brick.y - r : brick.y + brick.h + r;
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  } else if (minX < minY) {
    // side hit: horizontal face of the AABB
    ball.x = dLeft <= dRight ? brick.x - r : brick.x + brick.w + r;
    ball.vx = -ball.vx;
  } else {
    // top/bottom hit
    ball.y = dTop <= dBottom ? brick.y - r : brick.y + brick.h + r;
    ball.vy = -ball.vy;
  }
}
```

