test('brickHit: bottom-face hit flips vy and leaves vx untouched', () => {
  const bricks = loneBrick();
  const ball = { x: 120, y: 125, r: 7, vx: 40, vy: -260 };
  const prev = { x: 120, y: 135 };
  const hits = brickHit(ball, bricks, prev);
  assert.equal(hits.length, 1);
  assert.equal(bricks[0].alive, false);
  assert.ok(ball.vy > 0, 'vy should flip from up to down');
  assert.equal(ball.vx, 40, 'vx must stay exactly as it was on a top/bottom hit');
  assert.equal(ball.y, bricks[0].y + bricks[0].h + ball.r, 'ball is pushed out below the brick');
  assert.equal(collides(ball, bricks[0]), false, 'no residual overlap after the push-out');
});

test('brickHit: left-face hit flips vx and leaves vy untouched', () => {
