  assert.equal(hits.length, 1);
  assert.ok(ball.vx < 0, 'vx should flip from right to left');
  assert.equal(ball.vy, 40, 'vy must stay exactly as it was on a side hit');
  assert.equal(ball.x, bricks[0].x - ball.r, 'ball is pushed out to the left of the brick');
});

test('brickHit: corner hit flips both components', () => {
  const bricks = loneBrick();
  const ball = { x: 112, y: 112, r: 7, vx: 260, vy: 260 };
  const prev = { x: 88, y: 88 };
  const hits = brickHit(ball, bricks, prev);
  assert.equal(hits.length, 1);
  assert.ok(ball.vx < 0 && ball.vy < 0, 'a diagonal hit flips both components');
  assert.equal(ball.x, bricks[0].x - ball.r);
  assert.equal(ball.y, bricks[0].y - ball.r);
});

