if (state.running) {
  // Remember where the ball was BEFORE this frame's move: `brickHit`
  // sweeps the segment between the two positions so a fast ball cannot
  // tunnel through a brick (issue #1).
  const prev = { x: state.ball.x, y: state.ball.y };
  const lost = step(state, dt);
  if (lost) {
    state.lives -= 1;
    state.combo = 0;
    if (state.lives <= 0) {
      state.best = saveBest(globalThis.localStorage, state.score);
      Object.assign(state, createState(state.level));
